import { Vex } from './vex';
import { Element } from './element';
import { BoundingBoxComputation } from './boundingboxcomputation';
import { BoundingBox } from './boundingbox';
import { Font } from './fonts/vexflow_font';

function processOutline(outline, originX, originY, scaleX, scaleY, outlineFns) {
  let command;
  let x;
  let y;
  let i = 0;

  function nextX() { return originX + outline[i++] * scaleX; }
  function nextY() { return originY + outline[i++] * scaleY; }

  while (i < outline.length) {
    command = outline[i++];
    switch (command) {
      case 'm':
      case 'l':
        outlineFns[command](nextX(), nextY());
        break;
      case 'q':
        x = nextX();
        y = nextY();
        outlineFns.q(nextX(), nextY(), x, y);
        break;
      case 'b':
        x = nextX();
        y = nextY();
        outlineFns.b(nextX(), nextY(), nextX(), nextY(), x, y);
        break;
      default:
        break;
    }
  }
}

// VexFlowPatch: cache of a glyph outline's scaled, origin-relative path segments, keyed by the
// outline array (already cached per glyph code) and scale. Glyph.renderOutline replays these with
// just an add per point, instead of re-walking and re-coercing the outline string array (the
// outline is stored as strings) on every draw. WeakMap so entries vanish if the outline is GC'd.
const glyphSegmentCache = new WeakMap();

function getScaledGlyphSegments(outline, scale) {
  let byScale = glyphSegmentCache.get(outline);
  if (!byScale) {
    byScale = new Map();
    glyphSegmentCache.set(outline, byScale);
  }
  let segments = byScale.get(scale);
  if (!segments) {
    segments = [];
    // Record with origin 0,0 so the captured coordinates are purely scale*point (matching what
    // renderOutline's per-point `x_pos + ...` / `y_pos + ...` would add the position to). Same
    // scaleX/scaleY (scale, -scale) and consumption order as the original processOutline walk,
    // so replaying produces byte-identical absolute coordinates.
    processOutline(outline, 0, 0, scale, -scale, {
      m: (x, y) => segments.push(['m', x, y]),
      l: (x, y) => segments.push(['l', x, y]),
      q: (x1, y1, x, y) => segments.push(['q', x1, y1, x, y]),
      b: (x1, y1, x2, y2, x, y) => segments.push(['b', x1, y1, x2, y2, x, y]),
    });
    byScale.set(scale, segments);
  }
  return segments;
}

export class Glyph extends Element {
  /* Static methods used to implement loading / unloading of glyphs */
  static loadMetrics(font, code, cache) {
    const glyph = font.glyphs[code];
    if (!glyph) {
      throw new Vex.RERR('BadGlyph', `Glyph ${code} does not exist in font.`);
    }

    const x_min = glyph.x_min;
    const x_max = glyph.x_max;
    const ha = glyph.ha;

    let outline;

    if (glyph.o) {
      if (cache) {
        if (glyph.cached_outline) {
          outline = glyph.cached_outline;
        } else {
          outline = glyph.o.split(' ');
          glyph.cached_outline = outline;
        }
      } else {
        if (glyph.cached_outline) delete glyph.cached_outline;
        outline = glyph.o.split(' ');
      }

      return {
        x_min,
        x_max,
        ha,
        outline,
      };
    } else {
      throw new Vex.RERR('BadGlyph', `Glyph ${code} has no outline defined.`);
    }
  }

  /**
   * A quick and dirty static glyph renderer. Renders glyphs from the default
   * font defined in Vex.Flow.Font.
   *
   * @param {!Object} ctx The canvas context.
   * @param {number} x_pos X coordinate.
   * @param {number} y_pos Y coordinate.
   * @param {number} point The point size to use.
   * @param {string} val The glyph code in Vex.Flow.Font.
   * @param {boolean} nocache If set, disables caching of font outline.
   */
  static renderGlyph(ctx, x_pos, y_pos, point, val, nocache) {
    const scale = point * 72.0 / (Font.resolution * 100.0);
    const metrics = Glyph.loadMetrics(Font, val, !nocache);
    Glyph.renderOutline(ctx, metrics.outline, scale, x_pos, y_pos);
  }

  static renderOutline(ctx, outline, scale, x_pos, y_pos) {
    // VexFlowPatch: fast path for rendering contexts that can consume glyph outlines directly
    // (with caching), instead of receiving the outline's path commands one by one.
    // Used by OSMD's GeometricSkyBottomLineContext for the skyline/bottomline calculation.
    if (ctx.drawCachedGlyphOutline && ctx.drawCachedGlyphOutline(outline, scale, x_pos, y_pos)) {
      return;
    }
    ctx.beginPath();
    ctx.moveTo(x_pos, y_pos);
    // VexFlowPatch: replay cached scaled segments (position added per point) instead of re-walking
    // and re-coercing the outline string array on every draw. Produces byte-identical coordinates.
    const segments = getScaledGlyphSegments(outline, scale);
    for (let i = 0; i < segments.length; i++) {
      const s = segments[i];
      switch (s[0]) {
        case 'm': ctx.moveTo(x_pos + s[1], y_pos + s[2]); break;
        case 'l': ctx.lineTo(x_pos + s[1], y_pos + s[2]); break;
        case 'q': ctx.quadraticCurveTo(x_pos + s[1], y_pos + s[2], x_pos + s[3], y_pos + s[4]); break;
        case 'b': ctx.bezierCurveTo(x_pos + s[1], y_pos + s[2], x_pos + s[3], y_pos + s[4], x_pos + s[5], y_pos + s[6]); break;
        default: break;
      }
    }
    ctx.fill();
  }

  static getOutlineBoundingBox(outline, scale, x_pos, y_pos) {
    const bboxComp = new BoundingBoxComputation();

    processOutline(outline, x_pos, y_pos, scale, -scale, {
      m: bboxComp.addPoint.bind(bboxComp),
      l: bboxComp.addPoint.bind(bboxComp),
      q: bboxComp.addQuadraticCurve.bind(bboxComp),
      b: bboxComp.addBezierCurve.bind(bboxComp),
    });

    return new BoundingBox(
      bboxComp.x1,
      bboxComp.y1,
      bboxComp.width(),
      bboxComp.height()
    );
  }

  // VexFlowPatch: the note-width tables query glyph widths constantly during formatting
  // (the same few dozen (code, point) pairs, tens of thousands of times per render), each
  // time constructing a throwaway Glyph just to read getMetrics().width. That width is a
  // pure function of (code, point) — it is the cached bbox width — so memoize it on the font,
  // next to cached_outline / cached_bboxes.
  static cachedWidth(code, point) {
    const font = Font;
    let cache = font.cached_widths;
    if (!cache) {
      cache = Object.create(null);
      font.cached_widths = cache;
    }
    const key = code + '/' + point;
    let width = cache[key];
    if (width === undefined) {
      width = new Glyph(code, point).getMetrics().width;
      cache[key] = width;
    }
    return width;
  }

  /**
   * @constructor
   */
  constructor(code, point, options) {
    super();
    this.setAttribute('type', 'Glyph');

    this.code = code;
    this.point = point;
    this.options = {
      cache: true,
      font: Font,
    };

    this.metrics = null;
    this.x_shift = 0;
    this.y_shift = 0;

    this.originShift = {
      x: 0,
      y: 0,
    };

    if (options) {
      this.setOptions(options);
    } else {
      this.reset();
    }
  }

  setOptions(options) {
    Vex.Merge(this.options, options);
    this.reset();
  }

  setPoint(point) { this.point = point; return this; }
  setStave(stave) { this.stave = stave; return this; }
  setXShift(x_shift) { this.x_shift = x_shift; return this; }
  setYShift(y_shift) { this.y_shift = y_shift; return this; }

  reset() {
    this.scale = this.point * 72 / (this.options.font.resolution * 100);
    this.metrics = Glyph.loadMetrics(
      this.options.font,
      this.code,
      this.options.cache
    );
    // The origin is fixed at 0,0, so the box depends only on the outline and the
    // scale: every glyph with the same code and point size walks the same curves
    // again. Cache the four numbers on the font, next to cached_outline, and hand
    // out a fresh BoundingBox because callers keep a reference to it.
    if (this.options.cache) {
      const key = this.code + '/' + this.scale;
      let cache = this.options.font.cached_bboxes;
      if (!cache) {
        cache = Object.create(null);
        this.options.font.cached_bboxes = cache;
      }
      let box = cache[key];
      if (!box) {
        const computed = Glyph.getOutlineBoundingBox(
          this.metrics.outline,
          this.scale,
          0,
          0
        );
        box = [computed.getX(), computed.getY(), computed.getW(), computed.getH()];
        cache[key] = box;
      }
      this.bbox = new BoundingBox(box[0], box[1], box[2], box[3]);
    } else {
      this.bbox = Glyph.getOutlineBoundingBox(
        this.metrics.outline,
        this.scale,
        0,
        0
      );
    }
  }

  getMetrics() {
    if (!this.metrics) {
      throw new Vex.RuntimeError('BadGlyph', `Glyph ${this.code} is not initialized.`);
    }

    return {
      x_min: this.metrics.x_min * this.scale,
      x_max: this.metrics.x_max * this.scale,
      width: this.bbox.getW(),
      height: this.bbox.getH(),
    };
  }

  setOriginX(x) {
    const { bbox } = this;
    const originX = Math.abs(bbox.getX() / bbox.getW());
    const xShift = (x - originX) * bbox.getW();
    this.originShift.x = -xShift;
  }

  setOriginY(y) {
    const { bbox } = this;
    const originY = Math.abs(bbox.getY() / bbox.getH());
    const yShift = (y - originY) * bbox.getH();
    this.originShift.y = -yShift;
  }

  setOrigin(x, y) {
    this.setOriginX(x);
    this.setOriginY(y);
  }

  render(ctx, x, y) {
    if (!this.metrics) {
      throw new Vex.RuntimeError('BadGlyph', `Glyph ${this.code} is not initialized.`);
    }

    const outline = this.metrics.outline;
    const scale = this.scale;

    this.setRendered();
    this.applyStyle(ctx);
    Glyph.renderOutline(ctx, outline, scale, x + this.originShift.x, y + this.originShift.y);
    this.restoreStyle(ctx);
  }

  renderToStave(x) {
    this.checkContext();

    if (!this.metrics) {
      throw new Vex.RuntimeError('BadGlyph', `Glyph ${this.code} is not initialized.`);
    }

    if (!this.stave) {
      throw new Vex.RuntimeError('GlyphError', 'No valid stave');
    }

    const outline = this.metrics.outline;
    const scale = this.scale;

    this.setRendered();
    this.applyStyle();
    Glyph.renderOutline(this.context, outline, scale,
      x + this.x_shift, this.stave.getYForGlyphs() + this.y_shift);
    this.restoreStyle();
  }
}
